'use strict';
(()=>{const $=id=>document.getElementById(id),origin=document.querySelector('meta[name=justin-api-origin]')?.content||location.origin,username=new URLSearchParams(location.search).get('username')||'';let snapshot=null,busy=false;
 async function load(){if(busy)return;busy=true;$('inspect-refresh').disabled=true;try{const r=await fetch(new URL('/api/admin/inspect?username='+encodeURIComponent(username),origin),{credentials:'include',signal:AbortSignal.timeout(10000)}),data=await r.json();if(!r.ok)throw Error(data.error||'Could not inspect this save.');snapshot=data;$('inspect-title').textContent=data.player.username;$('inspect-status').textContent='Saved '+new Date(data.savedAt).toLocaleString()+' · inspected '+new Date(data.inspectedAt).toLocaleTimeString();$('inspect-content').hidden=false;const s=data.save,items=[['Wallet',Math.floor(s.bank).toLocaleString()],['Lifetime',Math.floor(s.lifetime).toLocaleString()],['Clicks',s.clicks.toLocaleString()],['Click power',JustinGame.perClick(s).toLocaleString()],['Points / second',JustinGame.perSecond(s).toLocaleString()],['Equipped',JustinGame.skins.find(x=>x.id===s.equipped)?.name||s.equipped],['Justins',s.owned.length],['Rebirths',s.rebirths],['Best combo',data.bestCombo],['Cosmetic worn',JustinGame.Cosmetics?.byId(s.cosmetics?.equipped)?.name||'none'],['Cosmetics owned',(s.cosmetics?.owned||[]).length+' / '+(JustinGame.cosmetics?.length||6)],['Ability',s.ability?.active?'running · '+JustinGame.Cosmetics.byId(s.ability.active.cosmetic).ability+' · '+s.ability.active.units+' hits':Date.now()>=(s.ability?.readyAt||0)?'ready':'cooldown until '+new Date(s.ability.readyAt).toLocaleTimeString()],['Last ability reward',s.ability?.last?Math.floor(s.ability.last.reward).toLocaleString()+' points':'none']];const nodes=items.map(([label,value])=>{const card=document.createElement('div'),name=document.createElement('small'),text=document.createElement('b');name.textContent=label;text.textContent=value;card.append(name,text);return card});$('inspect-summary').replaceChildren(...nodes);$('inspect-json').textContent=JSON.stringify(data,null,2);$('inspect-play').href='index.html?ownerView='+encodeURIComponent(data.player.username)}catch(e){$('inspect-status').textContent=e.message;$('inspect-content').hidden=true}finally{busy=false;$('inspect-refresh').disabled=false}}
 $('inspect-refresh').onclick=load;$('inspect-download').onclick=()=>{if(!snapshot)return;const url=URL.createObjectURL(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=snapshot.player.username+'-save.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};load();
})();
